import { sleep } from 'ut2';
import { Toast } from 'antd-mobile';
import { BizForm, BizFormItemInput, BizFormItemCaptcha } from 'mobile-more';
import DemoForm from './components/DemoForm';

// eslint-disable-next-line @typescript-eslint/no-unused-vars
async function sendCaptcha(mobile: string) {
  await sleep(2000);
  return;
}

function Demo() {
  const [form] = BizForm.useForm();

  const handleGetCaptcha = async () => {
    try {
      // \u9A8C\u8BC1\u624B\u673A\u53F7\u7801
      await form.validateFields(['mobile']);
    } catch (err: any) {
      Toast.show({ content: err.errorFields[0].errors[0] });
      return false;
    }

    //  \u53D1\u9001\u9A8C\u8BC1\u7801
    return sendCaptcha(form.getFieldValue(['mobile']));
  };

  return (
    <DemoForm
      form={form}
      initialValues={{
        mobile: '13000000000'
      }}
    >
      <BizFormItemInput name="mobile" label="\u624B\u673A\u53F7\u78012" type="mobile" required />
      <BizFormItemCaptcha name="captcha1" label="\u9A8C\u8BC1\u7801" onGetCaptcha={handleGetCaptcha} />
      <BizFormItemCaptcha
        name="captcha2"
        label="\u81EA\u5B9A\u4E49"
        second={120}
        initText="\u521D\u59CB\u6587\u672C"
        runText="\u5012\u8BA1\u65F6%ss"
        resetText="\u91CD\u65B0\u5012\u8BA1\u65F6"
        placeholder="6\u4F4D\u6570\u9A8C\u8BC1\u7801"
        captchaButtonProps={{
          size: 'small',
          color: 'default',
          fill: 'solid'
        }}
        onGetCaptcha={handleGetCaptcha}
      />
    </DemoForm>
  );
}

export default Demo;
