import { isArray } from 'ut2';
import {
  BizFormItemImageUploader,
  BizFormItemImageUploaderProps,
  BizFileViewer,
  ImageUploadItem
} from 'mobile-more';
import mockUpload from '../../services/mockUpload';

export interface ItemImageUploaderProps extends Partial<BizFormItemImageUploaderProps> {
  onUploadAfter?: (res: ImageUploadItem) => void;
  useThumbnailUrl?: boolean;
}

const ItemImageUploader: React.FC<ItemImageUploaderProps> = ({
  onUploadAfter,
  useThumbnailUrl = false,
  upload,
  ...restProps
}) => {
  return (
    <BizFormItemImageUploader
      maxCount={1}
      maxSize={10}
      upload={async (file: File) => {
        const res = await (upload ? upload(file) : mockUpload(file));
        onUploadAfter?.(res);
        if (useThumbnailUrl && !res.thumbnailUrl) {
          res.thumbnailUrl = BizFileViewer.getFileThumbUrl(file);
        }
        return res;
      }}
      extendRules={[
        {
          validator(_, value) {
            let hasErrorOrPending = false;
            if (isArray(value) && value.length > 0) {
              value.some((item) => {
                if (!item.extra || (!item.extra.fssid && !item.extra.fssId)) {
                  hasErrorOrPending = true;
                }
                return hasErrorOrPending;
              });
            }
            return hasErrorOrPending
              ? Promise.reject('\${label}\u4E0A\u4F20\u4E2D\u6216\u4E0A\u4F20\u5931\u8D25')
              : Promise.resolve();
          }
        }
      ]}
      {...restProps}
    />
  );
};

export default ItemImageUploader;
