import { toNumber } from 'ut2';

export interface ItemInputNumberProps extends BizFormItemInputProps {
  minValue?: string | number;
  maxValue?: string | number;
  suffix?: React.ReactNode;
}

const ItemInputNumber: React.FC<ItemInputNumberProps> = ({
  minValue,
  maxValue,
  suffix,
  inputProps,
  extendRules = [],
  ...restProps
}) => {
  return (
    <BizFormItemInput
      type="number"
      precision={2}
      min={0}
      useFloor
      inputProps={{ suffix, ...inputProps }}
      extendRules={[
        {
          validator(_, value) {
            // \u4F4E\u4EF7\u6821\u9A8C
            if (value) {
              if (minValue && toNumber(value) < toNumber(minValue)) {
                return Promise.reject('\${label}\u8FC7\u4F4E\uFF0C\u8BF7\u6838\u5BF9\uFF01');
              }
              if (maxValue && toNumber(value) > toNumber(maxValue)) {
                return Promise.reject('\${label}\u8FC7\u9AD8\uFF0C\u8BF7\u6838\u5BF9\uFF01');
              }
            }
            return Promise.resolve();
          }
        },
        ...extendRules
      ]}
      {...restProps}
    />
  );
};

export default ItemInputNumber;
