import classnames from 'classnames';
import styles from './index.module.less';

export interface CardViewProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  size?: 'small' | 'default';
  single?: boolean;
  compact?: boolean;
  title: React.ReactNode;
  optional?: boolean;
  optionalLabel?: React.ReactNode;
  tip?: React.ReactNode;
  extra?: React.ReactNode;
  styles?: {
    root?: React.CSSProperties;
    header?: React.CSSProperties;
    title?: React.CSSProperties;
    extra?: React.CSSProperties;
    tip?: React.CSSProperties;
    optional?: React.CSSProperties;
    content?: React.CSSProperties;
  };
  classes?: {
    root?: string;
    header?: string;
    title?: string;
    extra?: string;
    tip?: string;
    optional?: string;
    content?: string;
  };
}

const CardView: React.FC<CardViewProps> = ({
  title,
  optional = false,
  optionalLabel = '\u9009\u586B',
  tip,
  extra,
  size = 'default',
  single,
  compact,
  styles: outStyles,
  classes,
  style,
  className,
  children,
  ...restProps
}) => {
  return (
    <div
      className={classnames(
        styles.cardView,
        { [styles.small]: size === 'small', [styles.single]: single, [styles.compact]: compact },
        className,
        classes?.root
      )}
      style={{ ...style, ...outStyles?.root }}
      {...restProps}
    >
      <div className={classnames(styles.header, classes?.header)} style={outStyles?.header}>
        <div className={styles.headerInner}>
          <div className={classnames(styles.title, classes?.title)} style={outStyles?.title}>
            {title}
            {optional && (
              <span
                className={classnames(styles.optional, classes?.optional)}
                style={outStyles?.optional}
              >
                {optionalLabel}
              </span>
            )}
          </div>
          {extra && (
            <div className={classnames(styles.extra, classes?.extra)} style={outStyles?.extra}>
              {extra}
            </div>
          )}
        </div>
        {tip && (
          <div className={classnames(styles.tip, classes?.tip)} style={outStyles?.tip}>
            {tip}
          </div>
        )}
      </div>
      <div className={classnames(styles.content, classes?.content)} style={outStyles?.content}>
        {children}
      </div>
    </div>
  );
};

export default CardView;
