import styles from './index.module.less';

export interface MaterialProps {
  title: string;
  dot?: boolean;
  index?: number;
  desc?: React.ReactNode;
  image?: string;
  optional?: boolean;
  optionalLabel?: React.ReactNode;
}

const Material: React.FC<MaterialProps & { defaultProps?: Partial<MaterialProps> }> = (props) => {
  const mergeProps = { ...props?.defaultProps, ...props };
  const { title, dot, index, desc, image, optional = false, optionalLabel = '\u9009\u586B' } = mergeProps;
  const titlePrefix = dot ? '\u2022 ' : !isUndefined(index) ? index + '.' : '';

  return (
    <div className={styles.material}>
      <div className={styles.content}>
        <div className={styles.title}>
          {titlePrefix + title}
          {optional ? <span className={styles.optional}>{optionalLabel}</span> : null}
        </div>
        {desc && <div className={styles.desc}>{desc}</div>}
      </div>
      {image && (
        <div className={styles.media}>
          <img src={image} />
        </div>
      )}
    </div>
  );
};

export default Material;
