import { toInteger } from 'ut2';
import classNames from 'classnames';
import { Button } from 'antd-mobile';
import styles from './index.module.less';

export interface SubmitterProps extends React.HTMLAttributes<HTMLDivElement> {
  current: number;
  total: number;
  prevText?: React.ReactNode;
  nextText?: React.ReactNode;
  submitText?: React.ReactNode;
  onPrev?: () => void;
  onNext?: () => void;
  onSubmit?: () => void;
}

const Submitter: React.FC<SubmitterProps> = ({
  current: outCurrent = 1,
  total: outTotal,
  prevText = '\u4E0A\u4E00\u6B65',
  nextText = '\u4E0B\u4E00\u6B65',
  submitText = '\u63D0\u4EA4',
  onPrev,
  onNext,
  onSubmit,
  className,
  ...restProps
}) => {
  const current = toInteger(outCurrent < 1 ? 1 : outCurrent);
  const total = toInteger(outTotal < 1 ? 1 : outTotal);

  const isFirst = current === 1;
  const isLast = current === total;

  return (
    <div className={classNames(styles.submitter, className)} {...restProps}>
      {!isFirst && (
        <Button className={styles.prev} size="large" onClick={onPrev}>
          {prevText}
        </Button>
      )}
      <Button
        className={styles.next}
        size="large"
        onClick={isLast ? onSubmit : onNext}
        color="primary"
      >
        {isLast ? submitText : nextText}
      </Button>
    </div>
  );
};

export default Submitter;
